 const sphere=ctx.createRadialGradient(cx-R*.29,cy-R*.34,R*.04,cx,cy,R*1.12);sphere.addColorStop(0,'#1a6790');sphere.addColorStop(.42,'#0b3a5d');sphere.addColorStop(.76,'#082541');sphere.addColorStop(1,'#020d1b');ctx.beginPath();ctx.arc(cx,cy,R,0,2*Math.PI);ctx.fillStyle=sphere;ctx.fill();ctx.save();ctx.beginPath();ctx.arc(cx,cy,R,0,2*Math.PI);ctx.clip();
 // Geodetic graticule.
